ruleToc.chapterList:
@js:
(function () {
  var html = typeof result !== 'undefined' ? result : '';

  if (!html) {
    java.log('未找到 result 变量');
    return [];
  }

  var MARKER = '\\"chapters\\":[';
  var idx = html.indexOf(MARKER);
  if (idx < 0) {
    java.log('未找到 chapters 标记');
    return [];
  }

  var arrStart = idx + MARKER.length - 1;

  var i = arrStart, depth = 0, inStr = false, esc = false;
  while (i < html.length) {
    var c = html[i];
    if (esc) { esc = false; i++; continue; }
    if (c === '\\') { esc = true; i++; continue; }
    if (c === '"') { inStr = !inStr; i++; continue; }
    if (!inStr) {
      if (c === '[') depth++;
      else if (c === ']') { depth--; if (depth === 0) break; }
    }
    i++;
  }

  var raw = html.substring(arrStart, i + 1);
  var jsonStr = raw
    .replace(/\\\\/g, '\u0000')
    .replace(/\\"/g, '"')
    .replace(/\u0000/g, '\\');
var comicId = book.bookUrl.match(/\/comic\/([^/?#]+)/)?.[1];
java.log('bookid' + comicId);
  if (!comicId) {
    java.log('未能从 baseUrl 提取 comicId, bookurl:' + book.bookUrl);
    return [];
  }
  var chaptersRaw = JSON.parse(jsonStr);

  var chapters = chaptersRaw.map(function (ch) {
    return {
      number: ch.number,
      title:  ch.title,
      url:    '/read/' + comicId +'/' + ch.id,
    };
  });

  chapters.sort(function (a, b) { return a.number - b.number; });
  //java.log(JSON.stringify(chapters)	);
  return chapters;
})();
